sp_widget.client_script:
api.controller=function($rootScope, $scope, spUtil) {
	/* widget controller */
	var c = this;

	c.selectItem = function(idx) {

		var id = c.data.notes[idx].sys_id;
		console.log('Note Id= '+id);
		$rootScope.noteID = id;
		$rootScope.$emit('selectNote', id);
	}


	$rootScope.$on('deleteNote', function(event,data) {
		c.data.notes.splice($scope.notePos, 1);
	});

	c.snNoteUpdate = function(name, sys_id) {

		for(var i=0; i<c.data.notes.length; i++){
			if(c.data.notes[i].sys_id == name.data.sys_id) {

				if(name.data.record.note) {

					c.data.notes[i].note = name.data.record.note.display_value;
				}
				if(name.data.record.title) {

					c.data.notes[i].title = name.data.record.title.display_value;
				}

				c.server.update();

			}


		}

	}


	c.snNoteDelete = function(sysId) {

		c.server.get({

			action: 'sndeleteNote',
			noteId: sysId
		}).then(function(r) {

			c.data.notes = r.data.notes;
		});
	}



	spUtil.recordWatch($scope, "x_snc_createnotes_note","numberISNOTEMPTY^userDYNAMIC90d1921e5f510100a9ad2572f2b477fe",function(name) {

		console.log(name);
		console.log(name.data.operation);

		if(name.data.operation == 'update') {

			c.snNoteUpdate(name, name.data.sys_id);
		}

		if(name.data.operation == 'delete') {

			c.snNoteDelete(name.data.sys_id);
		}

		if(name.data.operation == 'insert') {
			c.server.refresh();
		}
	});


	c.newNote = function() {

		c.server.get({

			action: 'newNote'

		}).then(function(r) {
			c.data.noteID = r.data.noteId;
			$rootScope.$emit('selectNote', c.data.noteID);

		});
	}
};

sp_widget.script:
(function() {
	/* populate the 'data' object */
	/* e.g., data.table = $sp.getValue('table'); */

	data.notes = [];

	var noteRec = new GlideRecord('x_snc_createnotes_note');
	noteRec.addEncodedQuery('userDYNAMIC90d1921e5f510100a9ad2572f2b477fe');
	noteRec.orderByDesc('sys_created_on');
	noteRec.setLimit(options.maximum_records_to_display);
	noteRec.query();

	while(noteRec.next()) {

		noteObj = {};

		$sp.getRecordDisplayValues(noteObj, noteRec, "number,title,sys_id");

		noteObj.note = noteRec.getValue('note').slice(0,20);

		data.notes.push(noteObj);
	}


if(input) {
	if (input.action == 'sndeleteNote') {

		var delNote = new GlideRecord('x_snc_createnotes_note');


		if(delNote.get(input.noteId)) {
			delNote.deleteRecord();


		}
	}

	if(input.action == 'newNote') {

		var newNoteRec = new GlideRecord('x_snc_createnotes_note');
		newNoteRec.newRecord();
		var id = newNoteRec.insert();

		data.noteId = id;
		data.newNotes = {};

		$sp.getRecordDisplayValues(data.newNotes,newNoteRec,"sys_id,title,note");
	}
}

})();
